# What account and session does the unattended agent service run in?
#
# It matters because Ctrl+Alt+Del cannot be generated by the host: SendSAS requires a SERVICE
# running as LocalSystem (session 0), and the host is a LocalSystem process launched into the
# interactive session, which is not the same thing. Measured, not assumed - see the session 19
# notes in docs/HANDOVER.md.
#
# Pure ASCII on purpose (docs/HANDOVER.md section 10).

$ErrorActionPreference = 'SilentlyContinue'

Write-Output "=== services that look like ours ==="
$svcs = Get-CimInstance Win32_Service | Where-Object { $_.PathName -like '*RemoteSupport*' -or $_.Name -like '*RemoteSupport*' }
if (-not $svcs) { Write-Output "NONE - this machine has no unattended agent installed." }
foreach ($s in $svcs) {
    Write-Output ("name      : " + $s.Name)
    Write-Output ("display   : " + $s.DisplayName)
    Write-Output ("state     : " + $s.State + "   startmode: " + $s.StartMode)
    Write-Output ("account   : " + $s.StartName)
    Write-Output ("path      : " + $s.PathName)
    Write-Output ("pid       : " + $s.ProcessId)
    if ($s.ProcessId -gt 0) {
        $p = Get-Process -Id $s.ProcessId
        if ($p) { Write-Output ("session   : " + $p.SessionId + "   (0 means the services session, which is what SendSAS needs)") }
    }
    Write-Output ""
}

Write-Output "=== sas.dll present? ==="
$sas = Join-Path $env:SystemRoot 'System32\sas.dll'
if (Test-Path $sas) { Write-Output ("yes - " + (Get-Item $sas).VersionInfo.FileVersion) } else { Write-Output "NO - SendSAS cannot work on this machine at all" }

exit 0
